import app from 'flarum/forum/app';

/** The `whoSaidIt` forum attribute: today's quiz and, for a member, their day and choices. */

export function today() {
  return app.forum.attribute('whoSaidIt') || null;
}

/** Keep the card and the settings switches in step with what the page just did. */
export function remember(patch) {
  const state = today();
  if (!state) return;
  const {
    me,
    ...rest
  } = patch;
  Object.assign(state, rest);
  if (me && state.me) Object.assign(state.me, me);
}

/** Save the member's own choices (reminder, opt-out). */
export function saveMe(body) {
  return app.request({
    method: 'POST',
    url: app.forum.attribute('apiUrl') + '/who-said-it/me',
    body
  }).then(res => {
    remember({
      me: res
    });
    return res;
  });
}

/** "5h 12m", "12m", "45s". */
export function span(ms) {
  const s = Math.max(0, Math.round(ms / 1000));
  const h = Math.floor(s / 3600);
  const m = Math.floor(s % 3600 / 60);
  if (h) return `${h}h ${String(m).padStart(2, '0')}m`;
  if (m) return `${m}m`;
  return `${s}s`;
}