import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import LinkButton from 'flarum/common/components/LinkButton';
import Switch from 'flarum/common/components/Switch';
import { t } from '../common/text';
import { placed } from '../common/fofWidgets';
import { saveMe, today } from './state';
import TodayCard from './components/TodayCard';
import { ReminderNotification } from './notifications';
import { EXT, KEY, registerWidgets } from './widgets';
export { default as extend } from './extend';
/*
 * forum.js is loaded on every page, so it only wires things up: the route,
 * the sidebar link and card, two settings switches, the widgets and the
 * reminder. The quiz page is its own chunk.
 */

app.initializers.add('ernestdefoe/who-said-it', () => {
  app.routes['who-said-it'] = {
    path: '/who-said-it',
    component: () => import(/* webpackChunkName: 'forum/components/WhoSaidItPage', webpackMode: 'lazy-once' */ './components/WhoSaidItPage').then(async page => (await page.loadCore(), page))
  };
  app.notificationComponents.whoSaidItReminder = ReminderNotification;

  // String form: these components live in lazy chunks, and extending an imported copy patches one core never renders.
  extend('flarum/forum/components/IndexSidebar', 'navItems', function (items) {
    if (!today() || !app.forum.attribute('whoSaidItNav')) return;
    items.add('who-said-it', LinkButton.component({
      href: app.route('who-said-it'),
      icon: 'fas fa-quote-left'
    }, t('forum.nav')), 78);
  });

  // The card under the sidebar's links — not on the quiz page itself, and not where FoF's layout already places it.
  extend('flarum/forum/components/IndexSidebar', 'items', function (items) {
    if (!today() || placed(app, EXT, KEY) || m.route.get()?.split('?')[0] === '/who-said-it') return;
    items.add('who-said-it', m(TodayCard, null), -20);
  });
  extend('flarum/forum/components/SettingsPage', 'privacyItems', function (items) {
    const me = today()?.me;
    if (!me) return;
    items.add('whoSaidItQuotable', m(Switch, {
      state: !me.optedOut,
      loading: this.wsiQuoteSaving,
      onchange: on => save(this, 'wsiQuoteSaving', {
        optedOut: !on
      })
    }, t('forum.settings.quotable')), 50);
  });
  extend('flarum/forum/components/SettingsPage', 'notificationsItems', function (items) {
    const state = today();
    if (!state?.me || !state.canPlay) return;
    items.add('whoSaidItRemind', m(Switch, {
      state: state.me.remind,
      loading: this.wsiRemindSaving,
      onchange: on => save(this, 'wsiRemindSaving', {
        remind: on
      })
    }, t('forum.settings.remind')), 50);
  });

  // After sibling extensions (Bespoke) have set up their registries.
  setTimeout(() => registerWidgets(), 0);
});
function save(page, flag, body) {
  page[flag] = true;
  saveMe(body).catch(() => {}).finally(() => {
    page[flag] = false;
    m.redraw();
  });
}flarum.reg.addChunkModule('ernestdefoe-who-said-it:forum/components/WhoSaidItPage', '681', 'ernestdefoe-who-said-it', 'forum/components/WhoSaidItPage');
flarum.reg.addChunkModule('ernestdefoe-who-said-it:forum/components/WhoSaidItPage', '681', 'ernestdefoe-who-said-it', 'forum/api');